 14	internal static class OutputRenderer
 15	{
 16	    public static async Task RenderAsync(Stream output, QueryResult result, OutputFormat format)
 17	    {
 18	        switch (format)
 19	        {
 20	            case OutputFormat.Csv:
 21	                await RenderCsvAsync(output, result).ConfigureAwait(false);
 22	                return;
 23	            case OutputFormat.Json:
 24	                await RenderJsonAsync(output, result).ConfigureAwait(false);
 25	                return;
 26	            case OutputFormat.Table:
 27	                await RenderTableAsync(output, result).ConfigureAwait(false);
 28	                return;
 29	            default:
 30	                throw new ArgumentOutOfRangeException(nameof(format), format, null);
 31	        }
 32	    }
