 34	    private static async Task RenderCsvAsync(Stream output, QueryResult result)
 35	    {
 36	        await using var writer = CreateWriter(output);
 37	
 38	        switch (result)
 39	        {
 40	            case TableQueryResult tableResult:
 41	                await writer.WriteLineAsync(BuildCsvRow(tableResult.Headers)).ConfigureAwait(false);
 42	                foreach (var row in tableResult.Rows)
 43	                {
 44	                    await writer.WriteLineAsync(BuildCsvRow(row)).ConfigureAwait(false);
 45	                }
 46	                break;
 47	            case ScalarQueryResult scalarResult:
 48	                await writer.WriteLineAsync(FormatDecimal(scalarResult.Value)).ConfigureAwait(false);
 49	                break;
 50	            default:
 51	                throw new InvalidOperationException($"Unsupported result type: {result.GetType().Name}");
 52	        }
 53	
 54	        await writer.FlushAsync().ConfigureAwait(false);
 55	        await output.FlushAsync().ConfigureAwait(false);
 56	    }
 57	
 58	    private static async Task RenderJsonAsync(Stream output, QueryResult result)
 59	    {
 60	        using var jsonWriter = new Utf8JsonWriter(output, new JsonWriterOptions
 61	        {
 62	            Indented = false,
 63	            SkipValidation = false
 64	        });
 65	
 66	        switch (result)
 67	        {
 68	            case TableQueryResult tableResult:
 69	                jsonWriter.WriteStartArray();
 70	                foreach (var row in tableResult.Rows)
 71	                {
 72	                    jsonWriter.WriteStartObject();
 73	                    for (var i = 0; i < tableResult.Headers.Count; i++)
 74	                    {
 75	                        var header = tableResult.Headers[i];
 76	                        var value = i < row.Count ? row[i] : string.Empty;
 77	                        jsonWriter.WriteString(header, value);
 78	                    }
 79	                    jsonWriter.WriteEndObject();
 80	                }
 81	                jsonWriter.WriteEndArray();
 82	                break;
 83	            case ScalarQueryResult scalarResult:
 84	                jsonWriter.WriteNumberValue(scalarResult.Value);
 85	                break;
 86	            default:
 87	                throw new InvalidOperationException($"Unsupported result type: {result.GetType().Name}");
 88	        }
 89	
 90	        await jsonWriter.FlushAsync().ConfigureAwait(false);
 91	        await output.FlushAsync().ConfigureAwait(false);
 92	    }
 93	
 94	    private static async Task RenderTableAsync(Stream output, QueryResult result)
 95	    {
 96	        await using var writer = CreateWriter(output);
 97	
 98	        switch (result)
 99	        {
100	            case TableQueryResult tableResult:
101	                var widths = GetColumnWidths(tableResult.Headers, tableResult.Rows);
102	                await writer.WriteLineAsync(BuildTableRow(tableResult.Headers, widths)).ConfigureAwait(false);
103	                await writer.WriteLineAsync(BuildTableSeparator(widths)).ConfigureAwait(false);
104	                foreach (var row in tableResult.Rows)
105	                {
106	                    await writer.WriteLineAsync(BuildTableRow(row, widths)).ConfigureAwait(false);
107	                }
108	                break;
109	            case ScalarQueryResult scalarResult:
110	                await writer.WriteLineAsync(FormatDecimal(scalarResult.Value)).ConfigureAwait(false);
111	                break;
112	            default:
113	                throw new InvalidOperationException($"Unsupported result type: {result.GetType().Name}");
114	        }
115	
116	        await writer.FlushAsync().ConfigureAwait(false);
117	        await output.FlushAsync().ConfigureAwait(false);
118	    }
