  7	internal sealed class CsvTableProcessor
  8	{
  9	    public IReadOnlyList<string> ParseRequestedColumns(string columnsArgument)
 10	    {
 11	        return ParseRequestedColumns(new[] { columnsArgument });
 12	    }
 13	
 14	    public IReadOnlyList<string> ParseRequestedColumns(IEnumerable<string> columnArguments)
 15	    {
 16	        var requestedColumns = new List<string>();
 17	
 18	        foreach (var columnArgument in columnArguments)
 19	        {
 20	            if (string.IsNullOrWhiteSpace(columnArgument))
 21	            {
 22	                continue;
 23	            }
 24	
 25	            requestedColumns.AddRange(
 26	                columnArgument.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries));
 27	        }
 28	
 29	        return requestedColumns;
 30	    }
 31	
 32	    public ExecutionOutcome SelectColumns(
 33	        Stream input,
 34	        IReadOnlyList<string> requestedColumns)
 35	    {
 36	        if (requestedColumns.Count == 0)
 37	        {
 38	            return ExecutionOutcome.Failure("No columns were selected.");
 39	        }
 40	
 41	        using var parser = new TextFieldParser(input, Encoding.UTF8)
 42	        {
 43	            TextFieldType = FieldType.Delimited,
 44	            HasFieldsEnclosedInQuotes = true,
 45	            TrimWhiteSpace = false
 46	        };
 47	
 48	        parser.SetDelimiters(",");
 49	
