323	    public ExecutionOutcome GroupRows(
324	        Stream input,
325	        IReadOnlyList<string> groupByArguments)
326	    {
327	        if (!GroupByRequest.TryParse(groupByArguments, out var request, out var errorMessage))
328	        {
329	            return ExecutionOutcome.Failure(errorMessage);
330	        }
331	
332	        using var parser = CreateParser(input);
333	
334	        var headers = parser.ReadFields();
335	        if (headers is null)
336	        {
337	            return ExecutionOutcome.Failure("CSV file is empty.");
338	        }
339	
340	        if (!TryResolveColumnIndex(headers, request.GroupColumnName, out var groupColumnIndex))
341	        {
342	            return ExecutionOutcome.Failure($"Column not found: {request.GroupColumnName}");
343	        }
344	
345	        var aggregateColumnIndex = -1;
346	            if (request.AggregateKind is GroupByAggregateKind.Sum)
347	            {
348	                if (!TryResolveColumnIndex(headers, request.AggregateColumnName!, out aggregateColumnIndex))
349	                {
350	                    return ExecutionOutcome.Failure($"Column not found: {request.AggregateColumnName}");
351	                }
352	            }
353	
354	        var groups = new List<GroupAggregation>();
355	        var groupLookup = new Dictionary<string, GroupAggregation>(StringComparer.Ordinal);
356	
357	        while (!parser.EndOfData)
358	        {
359	            var fields = parser.ReadFields();
360	            if (fields is null)
361	            {
362	                continue;
363	            }
364	
365	            var groupValue = groupColumnIndex < fields.Length ? fields[groupColumnIndex] : string.Empty;
366	            if (!groupLookup.TryGetValue(groupValue, out var aggregation))
367	            {
368	                aggregation = new GroupAggregation(groupValue);
369	                groupLookup.Add(groupValue, aggregation);
370	                groups.Add(aggregation);
371	            }
372	
373	            aggregation.RowCount++;
374	
375	            if (request.AggregateKind is not GroupByAggregateKind.Sum)
376	            {
377	                continue;
378	            }
379	
380	            var candidateValue = aggregateColumnIndex < fields.Length ? fields[aggregateColumnIndex] : string.Empty;
381	            if (!decimal.TryParse(candidateValue, NumberStyles.Number, CultureInfo.InvariantCulture, out var numericValue))
382	            {
383	                return ExecutionOutcome.Failure($"Column must contain only numeric values: {request.AggregateColumnName}");
384	            }
385	
386	            aggregation.Sum += numericValue;
387	        }
388	
389	        var rows = new List<IReadOnlyList<string>>(groups.Count);
390	        foreach (var group in groups)
391	        {
392	            var aggregateValue = request.AggregateKind is GroupByAggregateKind.Count
393	                ? group.RowCount.ToString(CultureInfo.InvariantCulture)
394	                : FormatDecimal(group.Sum);
395	
396	            rows.Add([group.GroupValue, aggregateValue]);
397	        }
398	
399	        var resultHeaders = request.AggregateKind is GroupByAggregateKind.Count
400	            ? new[] { request.GroupColumnName, "count" }
401	            : new[] { request.GroupColumnName, request.AggregateColumnName! };
402	
403	        return ExecutionOutcome.Success(new TableQueryResult(resultHeaders, rows));
404	    }
