418	    private static bool TryResolveRequestedColumnIndexes(
419	        IReadOnlyList<string> headers,
420	        IReadOnlyList<string> requestedColumns,
421	        out int[] selectedIndexes,
422	        out string? errorMessage)
423	    {
424	        selectedIndexes = new int[requestedColumns.Count];
425	
426	        for (var i = 0; i < requestedColumns.Count; i++)
427	        {
428	            var requestedColumn = requestedColumns[i];
429	            var index = -1;
430	            for (var headerIndex = 0; headerIndex < headers.Count; headerIndex++)
431	            {
432	                if (string.Equals(headers[headerIndex], requestedColumn, StringComparison.OrdinalIgnoreCase))
433	                {
434	                    index = headerIndex;
435	                    break;
436	                }
437	            }
438	
439	            if (index < 0)
440	            {
441	                errorMessage = $"Column not found: {requestedColumn}";
442	                selectedIndexes = Array.Empty<int>();
443	                return false;
444	            }
445	
446	            selectedIndexes[i] = index;
447	        }
448	
449	        errorMessage = null;
450	        return true;
451	    }
